import{_ as t,l as n,o as e,c as s,v as i,p as l,x as r,d,i as h,S as c}from"./chunks/framework.InCnrqk-.js";const b=JSON.parse('{"title":"银行危机史与模式","description":"","frontmatter":{"title":"银行危机史与模式","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/banking-crises-history.md","filePath":"econ/banking-crises-history.md","lastUpdated":1789023840000}'),p={name:"econ/banking-crises-history.md"};function E(m,a,_,f,B,u){const o=n("Mermaid");return e(),s("div",null,[a[1]||(a[1]=i('<h1 id="银行危机史与模式" tabindex="-1">银行危机史与模式 <a class="header-anchor" href="#银行危机史与模式" aria-label="Permalink to &quot;银行危机史与模式&quot;">​</a></h1><div class="epigraph"><p>信贷扩张、房地产与短期负债堆在一起，然后突然要现金。细节换世纪，模式重复。</p><footer>—— Reinhart and Rogoff, This Time Is Different, 2009；Kindleberger, Manias, Panics, and Crashes</footer></div><p><a href="/econ/fiscal-monetary-dominance">上一课</a>把预算闭合写成谁适应谁。缺口换成中介史：银行危机不是同一条会计的另一个出口，而是流动性与偿付在资产负债表上同时爆。本课钉历史模式，影子挤兑下一课。不重写 <a href="/econ/diamond-dybvig">Diamond–Dybvig</a> 公式。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Reinhart–Rogoff 的跨世纪样本里，银行危机前后是债务/GDP、信贷/GDP 和房价的共同运动；「这次不同」几乎总是错的。Kindleberger 给叙事：狂热、外部事件、清算。宏观模型若只有代表性银行的 \\(\\phi\\)，会漏掉：危机是状态切换，不是 \\(\\sigma\\) 稍微大一点。缺口是把历史规律收成可对照的阶段，而不是年表。</p><p><span class="marginnote">Calomiris and Gorton 讨论恐慌是否信息还是纯粹流动性。Bordo 与 Schularick–Taylor 的信贷史。本课不把 RR 的财政乘数争论拖进来。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>读危机：先分清偿付（资产真坏了）与流动性（资产好但滚不过短债）。再看担保品（房地产）、杠杆（批发融资占比）、主权反馈（银行持有本国债）。政策对照：最后贷款人、存款保险、重组。与 HANK/GK：危机把 \\(\\phi\\) 或净值一次打穿，不是光滑的 \\(\\sigma\\) 冲击。</p>',8)),(e(),l(c,null,{default:r(()=>[h(o,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20BOOM%5B%22%E4%BF%A1%E8%B4%B7%E4%B8%8E%E6%88%BF%E4%BB%B7%22%5D%20--%3E%20LEV%5B%22%E7%9F%AD%E5%80%BA%E6%9D%A0%E6%9D%86%22%5D%0A%20%20LEV%20--%3E%20RUN%5B%22%E6%8C%A4%E5%85%91%20%2F%20%E5%81%9C%E6%BB%9A%22%5D%0A%20%20RUN%20--%3E%20FIRE%5B%22%E7%81%AB%E7%BA%BF%E5%87%BA%E5%94%AE%22%5D%0A%20%20FIRE%20--%3E%20SOV%5B%22%E4%B8%BB%E6%9D%83%E5%8F%8D%E9%A6%88%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=i('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>机制是期限错配加不透明资产：一旦滚动停止，\\(q\\) 下降验证最坏信念，净值蒸发，信贷供给崩溃（Gertler–Kiyotaki 的银行挤兑延伸）。历史模式是这个机制的反复校准，不是新理论。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>样本选择：只看大危机，会高估必然性；只看未爆的繁荣，会低估。下一课把「银行」换成表外影子，滚动市场换成回购与 ABCP。不写某国监管清单。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>银行危机的共同运动是信贷、担保品与短债，不是随机坏运气。</li><li>先分清偿付与流动性，再谈主权反馈。</li><li>出处：Reinhart and Rogoff, 2009；Kindleberger；Schularick and Taylor 信贷史。</li></ul>',6))])}const g=t(p,[["render",E]]);export{b as __pageData,g as default};
